import{_ as e,o as a,c as t,a1 as s}from"./chunks/framework.D8yXMOOQ.js";const g=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),n={name:"getting-started.md"};function l(h,i,r,o,d,p){return a(),t("div",null,[...i[0]||(i[0]=[s('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Laravel Integrity is a high-fidelity static AST &amp; dynamic Container Reflection suite designed to keep your codebase pristine. It prevents silent failures (like orphaned views or missing routes) from making it into production.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>PHP</strong>: 8.2 or higher</li><li><strong>Laravel</strong>: 11.x, 12.x, or 13.x</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Install the package as a development dependency via Composer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clcbws/laravel-integrity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dev</span></span></code></pre></div><p>Since the tool is strictly for analysis, you should generally install it only as a <code>dev</code> dependency.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Next, you should publish the default configuration file. This allows you to toggle specific checks and ignore certain files or directories:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=integrity-config</span></span></code></pre></div><p>This will create a <code>config/integrity.php</code> file in your application. See the <a href="/laravel-integrity/configuration.html">Configuration Guide</a> for a detailed breakdown of the available options.</p><h2 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h2><p>The primary entry point to run the suite is the <code>integrity:check</code> Artisan command.</p><h3 id="standard-audit" tabindex="-1">Standard Audit <a class="header-anchor" href="#standard-audit" aria-label="Permalink to &quot;Standard Audit&quot;">​</a></h3><p>Run all lightweight, static checks across the directories configured in <code>config/integrity.php</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integrity:check</span></span></code></pre></div><h3 id="full-check-pipeline" tabindex="-1">Full Check Pipeline <a class="header-anchor" href="#full-check-pipeline" aria-label="Permalink to &quot;Full Check Pipeline&quot;">​</a></h3><p>Include intensive checks that require booting database connections (like migration checks) or full Blade file compilations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integrity:check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --full</span></span></code></pre></div><h3 id="ci-cd-pipelines-strict-mode" tabindex="-1">CI / CD Pipelines (Strict Mode) <a class="header-anchor" href="#ci-cd-pipelines-strict-mode" aria-label="Permalink to &quot;CI / CD Pipelines (Strict Mode)&quot;">​</a></h3><p>To ensure the command fails with a non-zero exit code if any issues are identified, use the strict flag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integrity:check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strict</span></span></code></pre></div><h3 id="pre-commit-hooks-dirty-mode" tabindex="-1">Pre-commit Hooks (Dirty Mode) <a class="header-anchor" href="#pre-commit-hooks-dirty-mode" aria-label="Permalink to &quot;Pre-commit Hooks (Dirty Mode)&quot;">​</a></h3><p>If you only want to scan files that have been modified or staged in Git, use the dirty flag. This is significantly faster and perfect for pre-commit hooks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integrity:check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dirty</span></span></code></pre></div><h3 id="auto-remediation" tabindex="-1">Auto-Remediation <a class="header-anchor" href="#auto-remediation" aria-label="Permalink to &quot;Auto-Remediation&quot;">​</a></h3><p>Some hygiene issues, such as missing strict types, inline root facades (e.g. <code>\\DB::</code>), and unused imports can be automatically fixed by the tool:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integrity:fix</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Review the <a href="/laravel-integrity/checks-reference.html">Full Checks Reference</a> to understand everything the suite can catch.</li><li>Learn about the <a href="/laravel-integrity/architecture.html">Architecture</a> to understand how AST parsing and Container reflection are combined.</li></ul>',31)])])}const k=e(n,[["render",l]]);export{g as __pageData,k as default};
